import { test, expect } from '@playwright/test';

test.describe('Request Timeout Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/api/requests');
  });

  test('should display timeout error when request exceeds 10 seconds', async ({ page }) => {
    // Intercept the request and delay the response
    await page.route('**/api/long-running-request', (route) => {
      setTimeout(() => {
        route.abort('timedout');
      }, 11000);
    });

    // Click the button to trigger the request
    const requestButton = page.getByRole('button', { name: /start request/i });
    await expect(requestButton).toBeVisible();
    await requestButton.click();

    // Wait for the timeout error message to appear
    const errorMessage = page.getByText(/request timed out/i);
    await expect(errorMessage).toBeVisible();

    // Verify the error state is displayed
    const errorContainer = page.locator('[data-testid="error-container"]');
    await expect(errorContainer).toBeVisible();

    // Verify the request status shows as failed
    const statusIndicator = page.locator('[data-testid="request-status"]');
    await expect(statusIndicator).toContainText('Failed');

    // Verify the error details are present
    const errorDetails = page.locator('[data-testid="error-details"]');
    await expect(errorDetails).toContainText('Timeout');
  });

  test('should handle successful request and clear timeout error state', async ({ page }) => {
    // Intercept the request and respond successfully
    await page.route('**/api/long-running-request', (route) => {
      setTimeout(() => {
        route.fulfill({
          status: 200,
          body: JSON.stringify({ message: 'Request completed successfully' }),
        });
      }, 5000);
    });

    // Click the button to trigger the request
    const requestButton = page.getByRole('button', { name: /start request/i });
    await expect(requestButton).toBeVisible();
    await requestButton.click();

    // Wait for the success message
    const successMessage = page.getByText(/request completed successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify the success state is displayed
    const successContainer = page.locator('[data-testid="success-container"]');
    await expect(successContainer).toBeVisible();

    // Verify the request status shows as successful
    const statusIndicator = page.locator('[data-testid="request-status"]');
    await expect(statusIndicator).toContainText('Success');

    // Verify the error message is not visible
    const errorMessage = page.getByText(/request timed out/i);
    await expect(errorMessage).not.toBeVisible();

    // Verify the error container is not visible
    const errorContainer = page.locator('[data-testid="error-container"]');
    await expect(errorContainer).not.toBeVisible();
  });
});
